1	package release
2	
3	import (
4		"encoding/json"
5		"errors"
6		"fmt"
7		"os"
8		"path/filepath"
9		"sync"
10		"syscall"
11	)
12	
13	const (
14		stateFileName = "ledger.json"
15		lockFileName  = "ledger.lock"
16		stateVersion  = 1
17	)
18	
19	// Store 是一个本地配方批次台账，数据保存在调用方指定的目录中。
20	// 不同目录互相独立；多个 Store 可以安全并发提交（进程内互斥、进程间文件锁）。
21	type Store struct {
22		// dir 是打开时确定的绝对路径。即使传入相对目录，也在 Open 时按当时的
23		// 工作目录解析并固定下来：此后调用方切换进程工作目录，本对象的读取与
24		// 保存仍指向最初打开的位置，绝不会按新工作目录重新解释这个相对路径。
25		dir      string
26		lockFile *os.File
27		mu       sync.Mutex
28		state    *persistedState
29	}
30	
31	// Open 打开（或首次使用）位于 dir 的台账。
32	// 目录不存在时会创建；目录中没有台账文件时得到空台账；
33	// 台账文件已存在但没有任何内容（零字节，无论原本就是空文件还是使用中被截断）
34	// 时按损坏处理；已有台账文件无法读取、解析，存在两条配方编号与版本号
35	// 完全相同的配方记录，存在两条批次编号完全相同的批次记录，
36	// 任一配方版本的任一物料每份克数不是正数，
37	// 任一配方版本内同一物料编号出现多次，
38	// 任一批次绑定的配方版本未登记，
39	// 任一批次的计划份数不是正整数，或按其绑定的配方版本计算时某物料的
40	// 应投量（每份克数 × 计划份数）无法精确表示到千分之一克或超过
41	// 9223372036854775.807 克，
42	// 任一批次仍为草稿状态却带有投料记录，
43	// 任一批次已保存投料的登记序号与记录在列表中的位置不一致
44	// （第一条不为 1、零或负数、重号、漏号、跳号，或调换记录位置后
45	// 未同步序号；不同物料共用批次序号、不同批次各自从 1 开始），
46	// 已保存投料的物料编号不属于该批次绑定的配方版本，
47	// 或已保存的投料数量非法（单条不是正数，或同一批次同一物料累计实投
48	// 超过 9223372036854775.807 克）时，返回 ErrCorruptData（可用 errors.Is
49	// 判断），不会当成空台账继续保存，也不会返回可继续使用的台账对象。
50	//
51	// dir 可以是相对目录：其位置只按 Open 调用时的工作目录解析一次并固定。
52	// 打开之后即使进程切换了工作目录，本对象的查询与保存仍始终指向最初打开
53	// 的目录，不会按新工作目录重新解释相对路径；台账操作本身也不会改变调用
54	// 方的工作目录。切换工作目录后另行 Open 同一相对目录，得到的是绑定新位
55	// 置的独立对象，与此前的对象互不影响。
56	func Open(dir string) (*Store, error) {
57		if dir == "" {
58			return nil, errors.New("数据位置不能为空")
59		}
60		// 先按“打开那一刻”的工作目录把位置解析成绝对路径并固定。后续每次
61		// 查询与写入都会重新读取台账文件，若仍持有相对路径，调用方一旦切换
62		// 工作目录，相对路径就会指向别处——可能把已登记批次查成不存在，或把
63		// 变更读写到另一个同名台账。解析为绝对路径后，本对象始终绑定最初打
64		// 开的位置。filepath.Abs 只做词法解析、不访问文件系统，目录尚不存在
65		// （首次使用会自动创建）时也能得到稳定结果。
66		absDir, err := filepath.Abs(dir)
67		if err != nil {
68			return nil, fmt.Errorf("解析数据位置 %q 失败: %w", dir, err)
69		}
70		if err := os.MkdirAll(absDir, 0o755); err != nil {
71			return nil, fmt.Errorf("创建数据位置 %q 失败: %w", absDir, err)
72		}
73		info, err := os.Stat(absDir)
74		if err != nil {
75			return nil, fmt.Errorf("读取数据位置 %q 失败: %w", absDir, err)
76		}
77		if !info.IsDir() {
78			return nil, fmt.Errorf("数据位置 %q 不是目录", absDir)
79		}
80	
81		lockPath := filepath.Join(absDir, lockFileName)
82		lf, err := os.OpenFile(lockPath, os.O_CREATE|os.O_RDWR, 0o644)
83		if err != nil {
84			return nil, fmt.Errorf("打开锁文件失败: %w", err)
85		}
86	
87		s := &Store{dir: absDir, lockFile: lf}
88		if err := s.load(); err != nil {
89			lf.Close()
90			return nil, err
91		}
92		return s, nil
93	}
94	
95	// Close 释放台账占用的文件锁。
96	func (s *Store) Close() error {
97		s.mu.Lock()
98		defer s.mu.Unlock()
99		if s.lockFile == nil {
100			return nil
101		}
102		err := s.lockFile.Close()
103		s.lockFile = nil
104		return err
105	}
106	
107	func (s *Store) lockExclusive() error {
108		if s.lockFile == nil {
109			return errors.New("台账已关闭")
110		}
111		if err := syscall.Flock(int(s.lockFile.Fd()), syscall.LOCK_EX); err != nil {
112			return fmt.Errorf("锁定台账失败: %w", err)
113		}
114		return nil
115	}
116	
117	func (s *Store) lockShared() error {
118		if s.lockFile == nil {
119			return errors.New("台账已关闭")
120		}
121		if err := syscall.Flock(int(s.lockFile.Fd()), syscall.LOCK_SH); err != nil {
122			return fmt.Errorf("锁定台账失败: %w", err)
123		}
124		return nil
125	}
126	
127	func (s *Store) unlock() {
128		_ = syscall.Flock(int(s.lockFile.Fd()), syscall.LOCK_UN)
129	}
130	
131	func (s *Store) load() error {
132		data, err := os.ReadFile(filepath.Join(s.dir, stateFileName))
133		if err != nil {
134			if os.IsNotExist(err) {
135				s.state = &persistedState{Version: stateVersion, Requests: map[string]*requestRecord{}}
136				return nil
137			}
138			return fmt.Errorf("%w: 读取台账文件失败: %v", ErrCorruptData, err)
139		}
140		if len(data) == 0 {
141			// 区分“没有台账文件”与“已有文件但内容为空”：文件不存在才算首次使用，
142			// 零字节文件（原本就为空或使用中被截断）一律按损坏处理——既不能当成
143			// 空台账补写，也不能凭内存中的旧记录还原，调用方必须明确知道无法读取。
144			return fmt.Errorf("%w: 台账文件 %q 没有内容", ErrCorruptData, filepath.Join(s.dir, stateFileName))
145		}
146		var st persistedState
147		if err := json.Unmarshal(data, &st); err != nil {
148			return fmt.Errorf("%w: 台账文件解析失败: %v", ErrCorruptData, err)
149		}
150		if st.Version != stateVersion {
151			return fmt.Errorf("%w: 台账版本 %d 不受支持", ErrCorruptData, st.Version)
152		}
153		if err := validateState(&st); err != nil {
154			return err
155		}
156		if st.Requests == nil {
157			st.Requests = map[string]*requestRecord{}
158		}
159		s.state = &st
160		return nil
161	}
162	
163	// validateState 检查台账的引用完整性与数量合法性：
164	//   - 配方由配方编号与版本号共同识别，同一台账内每组编号+版本号只能
165	//     对应一条配方记录。只要同组出现第二条记录，无论名称、物料、每份克数
166	//     是否相同（即使内容完全一致），整份台账即视为损坏：不能挑第一条或
167	//     最后一条、不能合并物料、也不能自行删除一条后继续——重复记录会让
168	//     查询结果与批次的应投依据取决于文件中的排列顺序。重复版本即使尚未
169	//     被任何批次引用也一样拒绝，其他配方与批次完整也不能放行本次读取。
170	//   - 批次由批次编号唯一识别，同一台账内一个编号只能对应一条批次记录。
171	//     同一编号出现第二条记录，无论绑定的配方版本、计划份数、状态是否
172	//     相同（即使内容完全一致），整份台账即视为损坏：不能挑第一条或最后
173	//     一条、不能合并投料、不能自动改号或删除一条后继续——重复记录会让
174	//     同一编号查到的配方、投料与数量核对取决于文件中的排列顺序。其他
175	//     批次完整、投料数量吻合，或调用方只想查看另一个正常批次，都不能
176	//     放行本次读取；不同编号的批次绑定同一配方版本不受影响。
177	//   - 每个配方版本的每种物料，每份克数必须是正数——与登记时的规则一致。
178	//     任一版本（包括尚未被任何批次使用的版本）的任一物料为零或负数，
179	//     整份台账即视为损坏：不能改成最小用量、取绝对值、删除问题物料
180	//     或改用其他版本后继续，其他配方完整或批次数量恰好吻合也不能放行。
181	//   - 同一配方版本的物料列表内，每个物料编号只能出现一次——与登记时的
182	//     规则一致。任一版本（包括尚未被任何批次使用的版本）内同一物料编号
183	//     出现多次，整份台账即视为损坏：不能合并重复项、相加克数、丢弃其中
184	//     一条或由查询者挑一项作为依据，即使两条克数完全相同也不能放行；
185	//     不同版本、不同配方各自使用同一物料编号不受影响。
186	//   - 每个批次记录的配方编号与版本号必须共同指向一个已登记的配方版本。
187	//     任一批次找不到对应版本，整份台账即视为损坏——不能改用同编号的其他版本，
188	//     也不能按名称或物料内容替换，即使其他批次仍然完整也不能放行本次读取。
189	//   - 每个已保存批次的计划份数必须为正整数，且按该批次实际绑定的配方版本
190	//     计算，每种物料的应投量（每份克数 × 计划份数）都必须能精确表示到
191	//     千分之一克、且不超过 maxGramsMilli（9223372036854775.807 克）。
192	//     任一批次份数为零或负数，或任一物料的应投量无法精确表示/超出上限，
193	//     整份台账即视为损坏：不区分草稿、执行中还是已关闭，也不取决于本次
194	//     查询哪个批次——不能自动减少份数、改选其他配方版本或删除问题批次，
195	//     即使其他批次完整也不能放行。上限按每种物料分别判断：多种物料的
196	//     应投量相加超过上限不构成非法，单种物料恰好等于上限仍合法。
197	//   - 草稿批次不能带有任何投料记录：登记投料只允许操作执行中的批次，
198	//     草稿尚未开始执行，出现投料说明保存内容自相矛盾。任一草稿批次包含
199	//     至少一条投料，整份台账即视为损坏——即使这些投料的物料都属于绑定
200	//     版本、克数均为合法正数、累计实投恰好等于应投，也不能接受；不能
201	//     丢弃投料后当作干净草稿，不能把批次自动改为执行中或已关闭，也不
202	//     能替调用方改选配方版本来继续读取。台账里另有正常批次、调用方只
203	//     查询其他配方或批次，都不能绕过这项矛盾。没有投料的草稿不受影响；
204	//     执行中尚未投料、已关闭批次没有投料或仍有欠投超投都属正常。
205	//   - 每条已保存的投料数量必须是正数；同一批次内同一物料的累计实投
206	//     不得超过 maxGramsMilli（9223372036854775.807 克）。任一记录为零或
207	//     负数，或任一物料累计超限，整份台账即视为损坏——负数记录即使能被
208	//     正数抵消回范围内也不接受，超限也不能截断或忽略后继续。
209	//   - 每个批次的投料按保存位置共用一条从 1 开始的登记序列：第一条序号
210	//     必须为 1，此后每条依次加 1，且保存序号必须与该记录在列表中的位置
211	//     一致。不同物料的投料共用同一序列、不按物料各自编号；不同批次各自
212	//     从 1 开始。任一条记录的序号为零或负数、与前一条不连续（漏号、
213	//     跳号）、与其他记录重号，或记录调换了位置却未同步序号，整份台账即
214	//     视为损坏：即使物料归属与数量全部合法也不能接受，不能按自带序号或
215	//     投料时间重排、不能补号、不能删除问题记录后继续。投料时间由调用方
216	//     填写、从不参与排序，时间相同或乱序不能作为序号有误的依据。空投料
217	//     列表不构成序号错误，仍按批次状态规则处理。
218	//   - 每条已保存投料的物料编号必须属于该批次绑定的配方版本。归属以批次
219	//     实际绑定的版本为准：物料只出现在同编号的其他版本或其他配方中，
220	//     不能作为接受依据；也不能改选版本、补入物料或丢弃问题投料后继续。
221	func validateState(st *persistedState) error {
222		// 先按“配方编号 + 版本号”唯一标识遍历全部配方记录：同组出现第二条
223		// 记录即数据损坏，必须先于一切按标识查找的校验拒绝——否则重复记录
224		// 会让 findRecipe 总是返回排在前面的一条，查询结果与批次应投依据都
225		// 取决于文件排列顺序。完全相同的内容也不是合法重复。
226		versions := make(map[recipeKey]bool, len(st.Recipes))
227		for _, r := range st.Recipes {
228			if r == nil {
229				return fmt.Errorf("%w: 台账中存在空的配方记录", ErrCorruptData)
230			}
231			key := recipeKey{r.RecipeNo, r.Version}
232			if versions[key] {
233				return fmt.Errorf("%w: 配方编号 %q 版本号 %q 的配方记录重复",
234					ErrCorruptData, r.RecipeNo, r.Version)
235			}
236			versions[key] = true
237		}
238		for _, r := range st.Recipes {
239			seen := make(map[string]bool, len(r.Materials))
240			for _, m := range r.Materials {
241				if seen[m.MaterialNo] {
242					return fmt.Errorf("%w: 配方 %q 版本 %q 的物料编号 %q 重复",
243						ErrCorruptData, r.RecipeNo, r.Version, m.MaterialNo)
244				}
245				seen[m.MaterialNo] = true
246				if m.GramsMilli <= 0 {
247					return fmt.Errorf("%w: 配方 %q 版本 %q 物料 %q 的每份克数不是正数",
248						ErrCorruptData, r.RecipeNo, r.Version, m.MaterialNo)
249				}
250			}
251		}
252		// 再按批次编号唯一标识遍历全部批次记录：同一编号出现第二条记录即数据
253		// 损坏，必须先于一切按编号查找的校验拒绝——否则 findBatch 总是返回排在
254		// 前面的一条，同一编号查到的配方、投料与数量核对都取决于文件排列顺序。
255		// 两条记录即使绑定不同配方版本、计划份数不同或状态不同也属于重复；
256		// 内容完全一致同样不是合法记录。不能挑第一条或最后一条、不能合并投料、
257		// 也不能自动改号或删除一条后继续。不同批次绑定同一配方版本不受影响。
258		batchNos := make(map[string]bool, len(st.Batches))
259		for _, b := range st.Batches {
260			if b == nil {
261				return fmt.Errorf("%w: 台账中存在空的批次记录", ErrCorruptData)
262			}
263			if batchNos[b.BatchNo] {
264				return fmt.Errorf("%w: 批次编号 %q 的批次记录重复", ErrCorruptData, b.BatchNo)
265			}
266			batchNos[b.BatchNo] = true
267		}
268		for _, b := range st.Batches {
269			// 草稿尚未开始执行，不能登记投料；已保存的草稿却带着投料，
270			// 说明记录自相矛盾。必须先于配方归属与数量校验拒绝——否则
271			// 这份草稿还能被打开、调整份数或改选配方版本，留下按旧计划
272			// 登记的投料。不能丢弃投料当作干净草稿，不能自动改状态，也
273			// 不能改选版本后继续。
274			if b.Status == StatusDraft && len(b.Feedings) > 0 {
275				return fmt.Errorf("%w: 批次 %q 仍为草稿状态，却存在 %d 条投料记录",
276					ErrCorruptData, b.BatchNo, len(b.Feedings))
277			}
278			r := findRecipe(st, b.RecipeNo, b.RecipeVersion)
279			if r == nil {
280				return fmt.Errorf("%w: 批次 %q 绑定的配方 %q 版本 %q 未登记",
281					ErrCorruptData, b.BatchNo, b.RecipeNo, b.RecipeVersion)
282			}
283			if err := validateBatchPlan(b, r); err != nil {
284				return err
285			}
286			if err := validateFeedings(b, r); err != nil {
287				return err
288			}
289		}
290		return nil
291	}
292	
293	// validateBatchPlan 检查一个已保存批次的计划份数与按绑定配方版本算出的
294	// 应投量。数量规则本身（正份数、千分之一克精度、逐物料上限）统一由
295	// planRequirements 实现，这里只补充“读取已保存批次”场景的错误分类与
296	// 批次编号：份数非正或应投量非法都属于 ErrCorruptData。
297	// 归属以批次实际绑定的版本为准：换用同编号的其他版本或许能算得通，也
298	// 不能作为接受依据。计划数量是否合法与投料无关：尚未投料、实投不足或
299	// 超出应投都不影响。
300	func validateBatchPlan(b *batchRecord, r *recipeRecord) error {
301		if b.PlannedPortions <= 0 {
302			return fmt.Errorf("%w: 批次 %q 的计划份数 %d 不是正整数",
303				ErrCorruptData, b.BatchNo, b.PlannedPortions)
304		}
305		if _, err := planRequirements(r, b.PlannedPortions); err != nil {
306			return fmt.Errorf("%w: 批次 %q 的%v", ErrCorruptData, b.BatchNo, err)
307		}
308		return nil
309	}
310	
311	// validatePlanForRecipe 校验创建或调整草稿批次时，给定份数按配方版本逐
312	// 物料计算的应投量都能精确表示到千分之一克且不超过上限。份数本身的正
313	// 整数检查由调用方按各自输入规则完成（调整草稿时份数传 0 表示不改份数，
314	// 走到这里的必是最终采用的正份数）；数量规则统一由 planRequirements
315	// 实现，这里透传其逐物料说明（物料、配方编号、版本、份数），由调用方
316	// 按本次提交包装为 ErrInvalidInput。
317	func validatePlanForRecipe(r *recipeRecord, portions int) error {
318		_, err := planRequirements(r, portions)
319		return err
320	}
321	
322	// validateFeedings 检查一个批次内已保存投料的登记顺序、合法性与配方归属。
323	// 归属以批次绑定的配方版本 r 为准：每条投料的物料编号必须在 r 的物料
324	// 列表中，否则整份台账视为损坏。数量方面只判断数量本身是否合法，不判断
325	// 实投是否符合配方：无投料的物料累计为零属正常，不足或超过应投量也不
326	// 在此拒绝。
327	//
328	// 序号是整个批次共用的一条登记序列：不同物料的投料依次共用这组序号，
329	// 不按物料各自另起编号；不同批次则各自从 1 开始。列表中第 i 条（位置
330	// 从 1 起）的保存序号必须恰好为 i——第一条必须为 1，此后每条加 1。
331	// 零、负数、漏号、重号、跳号，或只调换了记录位置却没有同步序号，都说明
332	// 记录已经失去登记先后次序，整份台账视为损坏，即使物料归属与数量全部
333	// 合法也不能接受。投料时间只由调用方填写、从不参与排序，因此不能用来
334	// 佐证或否定序号：同一时刻登记、后一条时间早于前一条都属正常。该校验
335	// 只读取现有序号与位置，绝不重排、补号或删除任何投料。
336	func validateFeedings(b *batchRecord, r *recipeRecord) error {
337		acc := newFeedingAccumulator()
338		for i, f := range b.Feedings {
339			// 位置 i+1 上的保存序号必须就是 i+1：先于归属与数量校验判断，
340			// 因为一旦序号与位置不符，调用方已经无法按序号区分这是哪一次
341			// 成功登记——按错误的序号继续核对物料与数量没有意义。不能挑
342			// 记录自带的序号当真、不能按投料时间重排，也不能自行补号或
343			// 删除后继续。空投料列表不会进入这里，不构成序号错误。
344			pos := i + 1
345			if f.Seq != pos {
346				return fmt.Errorf("%w: 批次 %q 投料列表第 %d 条记录的登记序号为 %d，应为 %d：登记序号必须从 1 起按保存位置逐条连续加 1，不能为零或负数、重号、漏号、跳号或与位置不符",
347					ErrCorruptData, b.BatchNo, pos, f.Seq, pos)
348			}
349			belongs := false
350			for _, m := range r.Materials {
351				if m.MaterialNo == f.MaterialNo {
352					belongs = true
353					break
354				}
355			}
356			if !belongs {
357				return fmt.Errorf("%w: 批次 %q 的第 %d 条投料物料 %q 不属于其绑定的配方 %q 版本 %q",
358					ErrCorruptData, b.BatchNo, f.Seq, f.MaterialNo, b.RecipeNo, b.RecipeVersion)
359			}
360			if f.GramsMilli <= 0 {
361				return fmt.Errorf("%w: 批次 %q 物料 %q 的第 %d 条投料数量不是正数",
362					ErrCorruptData, b.BatchNo, f.MaterialNo, f.Seq)
363			}
364			if !acc.add(f.MaterialNo, f.GramsMilli) {
365				return fmt.Errorf("%w: 批次 %q 物料 %q 的累计实投超出上限 %s 克",
366					ErrCorruptData, b.BatchNo, f.MaterialNo, maxGramsMilli)
367			}
368		}
369		return nil
370	}
371	
372	// persist 先写临时文件再原子改名，并 fsync 目录，保证已提交数据可恢复。
373	func (s *Store) persist(st *persistedState) error {
374		data, err := json.MarshalIndent(st, "", "  ")
375		if err != nil {
376			return err
377		}
378		tmpPath := filepath.Join(s.dir, stateFileName+".tmp")
379		f, err := os.OpenFile(tmpPath, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0o644)
380		if err != nil {
381			return err
382		}
383		if _, err := f.Write(data); err != nil {
384			f.Close()
385			return err
386		}
387		if err := f.Sync(); err != nil {
388			f.Close()
389			return err
390		}
391		if err := f.Close(); err != nil {
392			return err
393		}
394		if err := os.Rename(tmpPath, filepath.Join(s.dir, stateFileName)); err != nil {
395			return err
396		}
397		if d, err := os.Open(s.dir); err == nil {
398			_ = d.Sync()
399			_ = d.Close()
400		}
401		return nil
402	}
403	
404	func cloneState(st *persistedState) (*persistedState, error) {
405		data, err := json.Marshal(st)
406		if err != nil {
407			return nil, err
408		}
409		var out persistedState
410		if err := json.Unmarshal(data, &out); err != nil {
411			return nil, err
412		}
413		if out.Requests == nil {
414			out.Requests = map[string]*requestRecord{}
415		}
416		return &out, nil
417	}
418	
419	// write 是所有写入操作的统一入口：
420	//   - reqNo 为空直接报错；
421	//   - 同一 reqNo 且操作与内容完全相同，返回第一次成功的结果（幂等重放）；
422	//   - 同一 reqNo 用于其他操作或不同内容，返回 ErrRequestConflict；
423	//   - apply 在状态副本上执行，返回校验错误时不落盘、不占用请求编号；
424	//   - apply 成功后，状态与请求记录一起原子落盘，再切换到内存状态。
425	func (s *Store) write(reqNo, op string, payload any, apply func(*persistedState) (json.RawMessage, error), out any) error {
426		if reqNo == "" {
427			return errors.New("请求编号不能为空")
428		}
429		s.mu.Lock()
430		defer s.mu.Unlock()
431		if err := s.lockExclusive(); err != nil {
432			return err
433		}
434		defer s.unlock()
435	
436		// 跨进程场景下，其他进程可能已提交新数据；加锁后重新加载，
437		// 确保在最新状态上应用变更，避免用旧快照覆盖其他进程的写入。
438		if err := s.load(); err != nil {
439			return err
440		}
441	
442		payloadRaw, err := json.Marshal(payload)
443		if err != nil {
444			return err
445		}
446		payloadStr := string(payloadRaw)
447	
448		if req, ok := s.state.Requests[reqNo]; ok {
449			if req.Op != op || req.Payload != payloadStr {
450				return fmt.Errorf("%w: 请求编号 %q 已用于操作 %q，不能再用于操作 %q 或不同内容",
451					ErrRequestConflict, reqNo, req.Op, op)
452			}
453			if err := json.Unmarshal(req.Result, out); err != nil {
454				return fmt.Errorf("重放请求 %q 的结果失败: %w", reqNo, err)
455			}
456			return nil
457		}
458	
459		clone, err := cloneState(s.state)
460		if err != nil {
461			return err
462		}
463		result, err := apply(clone)
464		if err != nil {
465			return err
466		}
467		clone.Requests[reqNo] = &requestRecord{Op: op, Payload: payloadStr, Result: result}
468		if err := s.persist(clone); err != nil {
469			return fmt.Errorf("保存台账失败: %w", err)
470		}
471		s.state = clone
472		if err := json.Unmarshal(result, out); err != nil {
473			return fmt.Errorf("解析请求结果失败: %w", err)
474		}
475		return nil
476	}
477	
478	// read 在共享锁下读取当前状态。
479	func (s *Store) read(fn func(*persistedState) error) error {
480		s.mu.Lock()
481		defer s.mu.Unlock()
482		if err := s.lockShared(); err != nil {
483			return err
484		}
485		defer s.unlock()
486		if err := s.load(); err != nil {
487			return err
488		}
489		return fn(s.state)
490	}
491	
492	// 视图构造：每次都从记录全新构造，返回的切片与内部状态完全隔离。
493	
494	func buildRecipeView(r *recipeRecord) *RecipeView {
495		mats := make([]MaterialView, 0, len(r.Materials))
496		for _, m := range r.Materials {
497			mats = append(mats, MaterialView{MaterialNo: m.MaterialNo, Grams: m.GramsMilli.String()})
498		}
499		return &RecipeView{RecipeNo: r.RecipeNo, Version: r.Version, Name: r.Name, Materials: mats}
500	}
501	
502	func buildBatchView(b *batchRecord, r *recipeRecord) (*BatchView, error) {
503		v := &BatchView{
504			BatchNo:         b.BatchNo,
505			RecipeNo:        r.RecipeNo,
506			RecipeVersion:   r.Version,
507			RecipeName:      r.Name,
508			PlannedPortions: b.PlannedPortions,
509			Status:          b.Status,
510			Feedings:        make([]FeedingView, 0, len(b.Feedings)),
511			Materials:       make([]MaterialRequirement, 0, len(r.Materials)),
512		}
513	
514		for _, f := range b.Feedings {
515			v.Feedings = append(v.Feedings, FeedingView{
516				Seq:        f.Seq,
517				MaterialNo: f.MaterialNo,
518				Grams:      f.GramsMilli.String(),
519				Time:       f.Time,
520				Registrar:  f.Registrar,
521			})
522		}
523	
524		// 按物料累计实投量；台账在读取时已通过 validateFeedings 校验，
525		// 这里仍用同一套累计规则防一手整数回绕。
526		acc := newFeedingAccumulator()
527		for _, f := range b.Feedings {
528			if !acc.add(f.MaterialNo, f.GramsMilli) {
529				return nil, fmt.Errorf("%w: 批次 %q 物料 %q 的累计实投超出可表示范围",
530					ErrCorruptData, b.BatchNo, f.MaterialNo)
531			}
532		}
533	
534		// 数量核对按配方物料逐项列出；应投量统一由 planRequirements 按本批次
535		// 绑定版本与计划份数计算，与创建、调整、读取校验共用同一套规则。
536		// 台账在读取时已通过 validateState 校验，这里仍防一手同一版本内物料
537		// 编号重复，避免返回重复的数量核对项。
538		required, err := planRequirements(r, b.PlannedPortions)
539		if err != nil {
540			return nil, fmt.Errorf("%w: 批次 %q 的%v", ErrCorruptData, b.BatchNo, err)
541		}
542		seen := make(map[string]bool, len(required))
543		for _, item := range required {
544			if seen[item.materialNo] {
545				return nil, fmt.Errorf("%w: 配方 %q 版本 %q 的物料编号 %q 重复",
546					ErrCorruptData, r.RecipeNo, r.Version, item.materialNo)
547			}
548			seen[item.materialNo] = true
549			act := acc.total(item.materialNo)
550			v.Materials = append(v.Materials, MaterialRequirement{
551				MaterialNo:      item.materialNo,
552				RequiredGrams:   item.requiredGrams.String(),
553				ActualGrams:     act.String(),
554				DifferenceGrams: (act - item.requiredGrams).String(),
555			})
556		}
557		return v, nil
558	}
559	
560	// recipeKey 是配方的唯一标识：配方编号与版本号的组合，采用精确匹配。
561	type recipeKey struct {
562		recipeNo string
563		version  string
564	}
565	
566	func findRecipe(st *persistedState, recipeNo, version string) *recipeRecord {
567		for _, r := range st.Recipes {
568			if r.RecipeNo == recipeNo && r.Version == version {
569				return r
570			}
571		}
572		return nil
573	}
574	
575	func findBatch(st *persistedState, batchNo string) *batchRecord {
576		for _, b := range st.Batches {
577			if b.BatchNo == batchNo {
578				return b
579			}
580		}
581		return nil
582	}
583

