160			t.Fatalf("损坏台账上投料应返回 ErrCorruptData，得到 %v", err)
161		}
162	
163		// 被拒绝的写入不改动文件、不占用请求编号。
164		after, err := os.ReadFile(filepath.Join(dir, stateFileName))
165		if err != nil {
166			t.Fatal(err)
167		}
