214			&batchRecord{
215				BatchNo: "B-closed-empty", RecipeNo: "R1", RecipeVersion: "v1",
216				PlannedPortions: 1, Status: StatusClosed,
217			},
218			// 已关闭、欠投（应投 100，实投 40）。
219			&batchRecord{
220				BatchNo: "B-closed-under", RecipeNo: "R1", RecipeVersion: "v1",
221				PlannedPortions: 1, Status: StatusClosed,
222				Feedings: []feedingRecord{
223					{Seq: 1, MaterialNo: "M1", GramsMilli: 40000, Time: fixedTime, Registrar: "张三"},
224				},
225			},
226			// 已关闭、超投（应投 100，实投 150）。
227			&batchRecord{
228				BatchNo: "B-closed-over", RecipeNo: "R1", RecipeVersion: "v1",
229				PlannedPortions: 1, Status: StatusClosed,
230				Feedings: []feedingRecord{
231					{Seq: 1, MaterialNo: "M1", GramsMilli: 150000, Time: fixedTime, Registrar: "张三"},
232				},
233			},
234		)
235	
236		s, err := Open(dir)
237		if err != nil {
238			t.Fatalf("无草稿投料的台账应正常打开: %v", err)
239		}
240		defer s.Close()
241	
242		// 合法草稿：数量核对列出全部配方物料，实投为零，差额为应投的负值。
243		draft, err := s.GetBatch("B-draft")
244		if err != nil {
245			t.Fatal(err)
246		}
247		if draft.Status != StatusDraft || len(draft.Feedings) != 0 {
248			t.Fatalf("草稿状态或投料不正确: %+v", draft)
249		}
250		if len(draft.Materials) != 1 {
251			t.Fatalf("草稿应列出全部配方物料，得到 %d 项", len(draft.Materials))
252		}
253		m := draft.Materials[0]
254		if m.MaterialNo != "M1" || m.RequiredGrams != "200" || m.ActualGrams != "0" || m.DifferenceGrams != "-200" {
255			t.Fatalf("草稿数量核对不正确: %+v", m)
256		}
257		// 无投料的草稿仍可调整份数。
258		adjusted, err := s.UpdateDraftBatch("u1", "B-draft", "", "", 3)
259		if err != nil {
260			t.Fatalf("无投料的草稿应可调整: %v", err)
261		}
262		if adjusted.PlannedPortions != 3 || adjusted.Status != StatusDraft {
263			t.Fatalf("调整结果不正确: %+v", adjusted)
264		}
265	
266		// 执行中尚未投料、已关闭无投料都正常。
267		for _, batchNo := range []string{"B-exec", "B-closed-empty"} {
268			view, err := s.GetBatch(batchNo)
269			if err != nil {
270				t.Fatalf("查询 %q 失败: %v", batchNo, err)
271			}
272			if len(view.Feedings) != 0 || view.Materials[0].ActualGrams != "0" {
273				t.Fatalf("%q 应无投料: %+v", batchNo, view)
274			}
275		}
276		// 已关闭批次的欠投、超投原样保留，关闭门槛不提高。
277		under, err := s.GetBatch("B-closed-under")
278		if err != nil {
279			t.Fatal(err)
280		}
281		if under.Materials[0].ActualGrams != "40" || under.Materials[0].DifferenceGrams != "-60" {
282			t.Fatalf("欠投应原样保留: %+v", under.Materials[0])
283		}
284		over, err := s.GetBatch("B-closed-over")
285		if err != nil {
286			t.Fatal(err)
287		}
288		if over.Materials[0].ActualGrams != "150" || over.Materials[0].DifferenceGrams != "50" {
289			t.Fatalf("超投应原样保留: %+v", over.Materials[0])
290		}
291	}
