182	// 台账打开后文件中批次份数被改成超限值（或零/负数）：
183	// 下一次查询或写入都必须返回 ErrCorruptData，即使操作的是另一个正常批次；
184	// 被拒绝的写入不改动文件、不占用请求编号；恢复合法份数后原记录继续可用。
185	func TestBatchPlanCorruptionAfterOpenDetectedOnNextAccess(t *testing.T) {
186		cases := []struct {
187			name    string
188			mutate  func(*batchRecord)
189			wantMsg []string
190		}{
191			{"份数改成两份导致应投超限", func(b *batchRecord) { b.PlannedPortions = 2 },
192				[]string{"B1", "2", "Mbig", "R9", "v1"}},
193			{"份数改成零", func(b *batchRecord) { b.PlannedPortions = 0 },
194				[]string{"B1", "0", "正整数"}},
195			{"份数改成负数", func(b *batchRecord) { b.PlannedPortions = -3 },
196				[]string{"B1", "-3", "正整数"}},
197		}
198		for _, tc := range cases {
199			t.Run(tc.name, func(t *testing.T) {
200				dir := t.TempDir()
201				s, err := Open(dir)
202				if err != nil {
203					t.Fatal(err)
204				}
205				defer s.Close()
206	
207				if _, err := s.RegisterRecipe("r9", "R9", "v1", "上限配方", []MaterialInput{
208					{MaterialNo: "Mbig", Grams: limitGrams},
209				}); err != nil {
210					t.Fatal(err)
211				}
212				if _, err := s.RegisterRecipe("r1", "R1", "v1", "配方一", []MaterialInput{
213					{MaterialNo: "M1", Grams: "100"},
214				}); err != nil {
215					t.Fatal(err)
216				}
217				// B1：执行中，一份上限配方（合法）；B2：执行中的正常批次。
218				if _, err := s.CreateBatch("b1", "B1", "R9", "v1", 1); err != nil {
219					t.Fatal(err)
220				}
221				if _, err := s.StartBatch("start-b1", "B1"); err != nil {
222					t.Fatal(err)
223				}
224				if _, err := s.CreateBatch("b2", "B2", "R1", "v1", 10); err != nil {
225					t.Fatal(err)
226				}
227				if _, err := s.StartBatch("start-b2", "B2"); err != nil {
228					t.Fatal(err)
229				}
230				fixedTime := time.Date(2026, 9, 1, 9, 0, 0, 0, time.UTC)
231				if _, err := s.AddFeeding("feed-b2", "B2", "M1", "5", fixedTime, "张三"); err != nil {
232					t.Fatal(err)
233				}
234	
235				good, err := os.ReadFile(filepath.Join(dir, stateFileName))
236				if err != nil {
237					t.Fatal(err)
238				}
239				var broken persistedState
240				if err := json.Unmarshal(good, &broken); err != nil {
241					t.Fatal(err)
242				}
243				for _, b := range broken.Batches {
244					if b.BatchNo == "B1" {
245						tc.mutate(b)
246					}
247				}
248				badBytes := writeStateFile(t, dir, &broken)
249	
250				// 查询损坏批次与正常批次、配方都必须失败。
251				for _, batchNo := range []string{"B1", "B2"} {
252					_, err := s.GetBatch(batchNo)
253					if !errors.Is(err, ErrCorruptData) {
254						t.Fatalf("文件损坏后查询批次 %q 应返回 ErrCorruptData，得到 %v", batchNo, err)
255					}
256					for _, want := range tc.wantMsg {
257						if batchNo == "B1" && !strings.Contains(err.Error(), want) {
258							t.Fatalf("错误信息应包含 %q，得到 %v", want, err)
259						}
260					}
261				}
262				if _, err := s.GetRecipe("R1", "v1"); !errors.Is(err, ErrCorruptData) {
263					t.Fatalf("整份台账损坏后配方查询也应失败，得到 %v", err)
264				}
265	
266				// 对正常批次 B2 的写入、登记新配方都不能借操作对象绕过。
267				if _, err := s.AddFeeding("feed-rejected", "B2", "M1", "1", time.Now(), "李四"); !errors.Is(err, ErrCorruptData) {
268					t.Fatalf("损坏台账上投料应返回 ErrCorruptData，得到 %v", err)
269				}
270				if _, err := s.CloseBatch("close-rejected", "B2"); !errors.Is(err, ErrCorruptData) {
271					t.Fatalf("损坏台账上关闭批次应返回 ErrCorruptData，得到 %v", err)
272				}
273				if _, err := s.RegisterRecipe("r-rejected", "R3", "v1", "新配方", []MaterialInput{
274					{MaterialNo: "M1", Grams: "1"},
275				}); !errors.Is(err, ErrCorruptData) {
276					t.Fatalf("损坏台账上登记配方应返回 ErrCorruptData，得到 %v", err)
277				}
278	
279				// 被拒绝的操作不改文件、不留请求记录。
280				after, err := os.ReadFile(filepath.Join(dir, stateFileName))
281				if err != nil {
282					t.Fatal(err)
283				}
284				if !bytes.Equal(after, badBytes) {
285					t.Fatalf("被拒绝的写入不应改动台账文件")
286				}
287				if bytes.Contains(after, []byte("feed-rejected")) ||
288					bytes.Contains(after, []byte("close-rejected")) ||
289					bytes.Contains(after, []byte("R3")) {
290					t.Fatalf("被拒绝的写入不应留下请求结果或业务记录")
291				}
292	
293				// 恢复合法计划后原记录完整可用；被拒绝过的编号仍可合法提交。
294				if err := os.WriteFile(filepath.Join(dir, stateFileName), good, 0o644); err != nil {
295					t.Fatal(err)
296				}
297				b1, err := s.GetBatch("B1")
298				if err != nil {
299					t.Fatalf("恢复后查询 B1 应成功: %v", err)
300				}
301				if b1.PlannedPortions != 1 || b1.Status != StatusExecuting {
302					t.Fatalf("B1 原计划应保留: %+v", b1)
303				}
304				if b1.Materials[0].RequiredGrams != limitGrams {
305					t.Fatalf("B1 应投量应为上限，得到 %s", b1.Materials[0].RequiredGrams)
306				}
307				b2, err := s.GetBatch("B2")
308				if err != nil {
309					t.Fatalf("恢复后查询 B2 应成功: %v", err)
310				}
311				if len(b2.Feedings) != 1 || b2.Feedings[0].Grams != "5" {
312					t.Fatalf("B2 原有投料应保留: %+v", b2.Feedings)
313				}
314				if _, err := s.AddFeeding("feed-rejected", "B2", "M1", "1", time.Now(), "李四"); err != nil {
315					t.Fatalf("被拒绝过的请求编号应仍可合法使用: %v", err)
316				}
317				if c, err := s.CloseBatch("close-rejected", "B2"); err != nil || c.Status != StatusClosed {
318					t.Fatalf("被拒绝过的关闭编号应仍可合法使用: %v %+v", err, c)
319				}
320			})
321		}
322	}
